  L5SAR.ek L ar LB FF sp scr [(PMSPA.o_src PeCLayoutB.CADDR_B fb + 256, 40)] M2 M3 -> mem_grows M2 M3 ->
  PM.parser_at RSEGS PeCLayoutB.CADDR_B PMSPA.accA PMSPA.annA M2 (PMSPA.o_p PeCLayoutB.CADDR_B fb) ois s ->
